<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require_once dirname(__DIR__,2).'/app/BusinessAdminService.php';
require_once dirname(__DIR__,2).'/app/BusinessAdminFilters.php';
require_once dirname(__DIR__,2).'/app/BusinessSubscriptionAdminService.php';
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: private, no-store');
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el portal.');}
$_SESSION['last_seen']=time();
$filters=[];foreach(['query','category','origin','account','plan','verification'] as $key)$filters[$key]=is_string($_GET[$key]??null)?trim($_GET[$key]):'';
$filters['destination']=max(0,(int)($_GET['destination']??0));
$review=($_GET['view']??'')==='review';$error='';$rows=[];$applications=[];
try{
    $all=(new BusinessAdminService(db(),private_storage_path('business-image-references')))->all();
    $related=db()->query('SELECT business_id FROM lead_business_links UNION SELECT business_id FROM business_account_applications WHERE business_id IS NOT NULL UNION SELECT s.business_id FROM business_subscription_payment_evidence p JOIN business_subscriptions s ON s.id=p.subscription_id')->fetchAll(PDO::FETCH_COLUMN);
    $ids=array_fill_keys(array_map('intval',$related),true);
    foreach($all as $row)if(($review?$row['publication_status']==='draft':isset($ids[(int)$row['id']]))&&BusinessAdminFilters::matches($row,$filters))$rows[]=$row;
    $applications=db()->query('SELECT id,business_name,status FROM business_account_applications WHERE business_id IS NULL AND status IN ("pending","in_review") ORDER BY created_at,id')->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){if(class_exists('PortalIncidents',false))PortalIncidents::technical($e,'atencion_comercios');$error='No se pudo cargar la cola. Comprueba las migraciones de solicitudes y vinculación.';http_response_code(503);}
$filterOptions=['destination'=>[],'category'=>[],'origin'=>['public_import'=>'Importación pública','admin_created'=>'Creación administrativa','owner_submitted'=>'Solicitud del negocio'],'plan'=>['free'=>'Gratis','featured'=>'Destacado','page'=>'Página Comercial','page_premium'=>'Premium'],'verification'=>['PUBLICO'=>'Dato público','VERIFICADO'=>'Dato verificado','ACTIVO'=>'Activo','PENDIENTE_REVISION'=>'Pendiente de revisión']];
foreach($all??[] as $optionRow){$filterOptions['destination'][$optionRow['destination_id']]=$optionRow['destination_name'];foreach($optionRow['category_codes'] as $index=>$code)$filterOptions['category'][$code]=$optionRow['category_labels'][$index]??$code;}
$total=count($rows);$page=min(max(1,(int)($_GET['page']??1)),max(1,(int)ceil($total/25)));$rows=array_slice($rows,($page-1)*25,25);
$publisher=new BusinessSubscriptionAdminService(db());
$queueReturn='atencion-comercios.php?'.http_build_query($_GET);
$title=$review?'Revisión y publicación':'Atención a comercios';
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?=esc($title)?> | Administración</title><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page"><h1><?=esc($title)?></h1><?php require __DIR__.'/_navigation.php'; ?><?php if($error):?><p role="alert" class="notice"><?=esc($error)?></p><?php else:?><p><?=$review?'Fichas en borrador de cualquier origen. Abrir una ficha no la publica.':'Fichas con solicitud de cuenta o relación informativa confirmada. También incluye comprobantes recibidos. Tener una cuenta o un canal por sí solo no indica interés recibido.'?></p><form method="get" class="admin-inbox-filter"><input type="hidden" name="view" value="<?=$review?'review':'attention'?>"><label>Buscar negocio o lugar<input type="search" name="query" value="<?=esc($filters['query'])?>"></label><label>Cuenta asociada<select data-native-select name="account"><option value="">Todas</option><option value="yes" <?=$filters['account']==='yes'?'selected':''?>>Con cuenta</option><option value="no" <?=$filters['account']==='no'?'selected':''?>>Sin cuenta</option></select></label><?php foreach(['destination'=>'Lugar','category'=>'Categoría','origin'=>'Origen','plan'=>'Suscripción','verification'=>'Verificación'] as $key=>$label):?><label><?=esc($label)?><select name="<?=esc($key)?>"><option value="">Todos</option><?php foreach($filterOptions[$key] as $value=>$name):?><option value="<?=esc($value)?>" <?=(string)$filters[$key]===(string)$value?'selected':''?>><?=esc($name)?></option><?php endforeach ?></select></label><?php endforeach ?><button class="pill">Filtrar</button><a href="atencion-comercios.php?view=<?=$review?'review':'attention'?>">Limpiar</a></form><p><?=$total?> negocios distintos · <?=count($applications)?> solicitudes pendientes sin ficha</p><section><h2>Solicitudes sin ficha</h2><?php if(!$applications):?><p>No hay solicitudes pendientes sin ficha.</p><?php endif ?><?php foreach($applications as $item):?><p><?=esc($item['business_name'])?> · <?=esc($item['status'])?> <a href="solicitud-detalle.php?type=account&amp;id=<?=esc($item['id'])?>&amp;return=<?=rawurlencode($queueReturn)?>" target="_blank" rel="noopener">Revisar solicitud ↗</a></p><?php endforeach ?></section><section><h2>Fichas de negocios</h2><div class="destination-admin-table"><table><thead><tr><th>Negocio</th><th>Origen y estado</th><th>Cuenta</th><th>Siguiente paso</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=esc($row['display_name'])?><br><?=esc($row['destination_name'])?> · #<?=esc($row['id'])?></td><td><?=esc($row['record_origin'])?><br><?=esc($row['publication_status'])?> · <?=esc($row['subscription_status'])?></td><td><?=trim((string)$row['account_email'])!==''?'Cuenta asociada':'Sin cuenta asociada'?></td><td><?php if($review):$blockers=$publisher->publicationBlockers((int)$row['id']);?><p><?=esc($blockers[0]??'Requisitos comprobados; revisar la ficha antes de publicar.')?></p><?php endif ?><a href="negocios.php?id=<?=esc($row['id'])?>" target="_blank" rel="noopener">Abrir negocio ↗</a> · <a href="suscripciones.php?id=<?=esc($row['id'])?>">Revisar requisitos de publicación</a></td></tr><?php endforeach ?><?php if(!$rows):?><tr><td colspan="4">No hay fichas en esta cola.</td></tr><?php endif ?></tbody></table></div><nav aria-label="Páginas de negocios"><?php if($page>1):?><a href="?<?=esc(http_build_query(array_merge($_GET,['page'=>$page-1])))?>">← Anterior</a><?php endif ?> <span>Página <?=$page?></span> <?php if($page*25<$total):?><a href="?<?=esc(http_build_query(array_merge($_GET,['page'=>$page+1])))?>">Siguiente →</a><?php endif ?></nav></section><?php endif ?><script src="<?=esc(admin_asset('select-flotante.js'))?>" defer></script></main></body></html>
